//! PathVisualizer matching CesiumJS `DataSources/PathVisualizer.js` (Apache-2.0).

use std::cell::RefCell;
use std::collections::HashMap;
use std::rc::Rc;

use crate::{
    BoundingSphere, BoundingSphereState, Cartesian3, DeveloperError, Entity, EntityCollection,
    JulianDate, ListenerId,
};

/// Simulated polyline path primitive generated by `PathVisualizer`.
#[derive(Clone, Debug, Default)]
pub struct PathPrimitive {
    pub positions: Vec<Cartesian3>,
    pub width: f64,
    pub show: bool,
    pub resolution: f64,
    pub lead_time: f64,
    pub trail_time: f64,
    pub bounding_sphere: BoundingSphere,
}

impl PathPrimitive {
    pub fn new() -> Self {
        Self {
            positions: Vec::new(),
            width: 1.0,
            show: true,
            resolution: 60.0,
            lead_time: 0.0,
            trail_time: 0.0,
            bounding_sphere: BoundingSphere::default(),
        }
    }
}

/// Simulated scene for `PathVisualizer`.
#[derive(Clone, Debug, Default)]
pub struct PathVisualizerScene {
    pub primitives: Rc<RefCell<Vec<PathPrimitive>>>,
}

impl PathVisualizerScene {
    pub fn new() -> Self {
        Self {
            primitives: Rc::new(RefCell::new(Vec::new())),
        }
    }

    pub fn primitives(&self) -> Rc<RefCell<Vec<PathPrimitive>>> {
        Rc::clone(&self.primitives)
    }
}

struct PathData {
    primitive_idx: usize,
}

/// A Visualizer which maps Entity.path to a polyline primitive path.
pub struct PathVisualizer {
    scene: Rc<RefCell<PathVisualizerScene>>,
    entity_collection: Rc<RefCell<EntityCollection>>,
    items: HashMap<String, PathData>,
    collection_subscription: Option<ListenerId>,
    destroyed: bool,
}

impl PathVisualizer {
    /// Creates a new `PathVisualizer`.
    pub fn new(
        scene: Option<Rc<RefCell<PathVisualizerScene>>>,
        entity_collection: Option<Rc<RefCell<EntityCollection>>>,
    ) -> Result<Self, DeveloperError> {
        let scene = scene.ok_or_else(|| DeveloperError::new("scene is required."))?;
        let entity_collection = entity_collection
            .ok_or_else(|| DeveloperError::new("entityCollection is required."))?;

        let mut visualizer = Self {
            scene,
            entity_collection: Rc::clone(&entity_collection),
            items: HashMap::new(),
            collection_subscription: None,
            destroyed: false,
        };

        visualizer.setup_collection_listener();
        Ok(visualizer)
    }

    fn setup_collection_listener(&mut self) {
        let sub = self.entity_collection.borrow_mut().collection_changed.add_listener(|_| {});
        self.collection_subscription = Some(sub);
    }

    /// Updates paths to match entity definitions at given time.
    pub fn update(&mut self, time: Option<JulianDate>) -> Result<bool, DeveloperError> {
        let time = time.ok_or_else(|| DeveloperError::new("time is required."))?;

        let binding = self.entity_collection.borrow();
        let entities = binding.values();
        let mut primitives = self.scene.borrow().primitives.borrow().clone();

        for entity in entities {
            let path_graphics = match &entity.path {
                Some(p) => p,
                None => {
                    if let Some(data) = self.items.remove(&entity.id) {
                        if data.primitive_idx < primitives.len() {
                            primitives.remove(data.primitive_idx);
                        }
                    }
                    continue;
                }
            };

            let position_prop = match &entity.position {
                Some(p) => p,
                None => {
                    if let Some(data) = self.items.remove(&entity.id) {
                        if data.primitive_idx < primitives.len() {
                            primitives.remove(data.primitive_idx);
                        }
                    }
                    continue;
                }
            };

            let show = entity.is_showing()
                && entity.is_available(&time)
                && path_graphics
                    .show
                    .as_ref()
                    .and_then(|p| p.get_value(Some(&time)))
                    .unwrap_or(true);

            if !show {
                if let Some(data) = self.items.get(&entity.id) {
                    if data.primitive_idx < primitives.len() {
                        primitives[data.primitive_idx].show = false;
                    }
                }
                continue;
            }

            let width = path_graphics
                .width
                .as_ref()
                .and_then(|p| p.get_value(Some(&time)))
                .unwrap_or(1.0);

            let resolution = path_graphics
                .resolution
                .as_ref()
                .and_then(|p| p.get_value(Some(&time)))
                .unwrap_or(60.0);

            let lead_time = path_graphics
                .lead_time
                .as_ref()
                .and_then(|p| p.get_value(Some(&time)))
                .unwrap_or(0.0);

            let trail_time = path_graphics
                .trail_time
                .as_ref()
                .and_then(|p| p.get_value(Some(&time)))
                .unwrap_or(0.0);

            // Sample points from trail_time ago up to lead_time ahead
            let mut positions = Vec::new();
            let step = resolution.max(1.0);
            let start_sec = -trail_time;
            let end_sec = lead_time;

            let mut cur_sec = start_sec;
            while cur_sec <= end_sec {
                let sample_time = time.add_seconds(cur_sec);
                if let Some(pos) = position_prop.get_value(Some(&sample_time)) {
                    positions.push(pos);
                }
                cur_sec += step;
            }

            // Always sample at current time if not already
            if positions.is_empty() {
                if let Some(current_pos) = position_prop.get_value(Some(&time)) {
                    positions.push(current_pos);
                }
            }

            let bounding_sphere = if !positions.is_empty() {
                let dvec_points: Vec<glam::DVec3> = positions
                    .iter()
                    .map(|p| glam::DVec3::new(p.x, p.y, p.z))
                    .collect();
                BoundingSphere::from_points(&dvec_points).unwrap_or_default()
            } else {
                BoundingSphere::default()
            };

            if let Some(data) = self.items.get_mut(&entity.id) {
                if data.primitive_idx < primitives.len() {
                    let prim = &mut primitives[data.primitive_idx];
                    prim.show = true;
                    prim.width = width;
                    prim.resolution = resolution;
                    prim.lead_time = lead_time;
                    prim.trail_time = trail_time;
                    prim.positions = positions;
                    prim.bounding_sphere = bounding_sphere;
                }
            } else {
                let mut prim = PathPrimitive::new();
                prim.show = true;
                prim.width = width;
                prim.resolution = resolution;
                prim.lead_time = lead_time;
                prim.trail_time = trail_time;
                prim.positions = positions;
                prim.bounding_sphere = bounding_sphere;
                primitives.push(prim);
                self.items.insert(
                    entity.id.clone(),
                    PathData {
                        primitive_idx: primitives.len() - 1,
                    },
                );
            }
        }

        *self.scene.borrow().primitives.borrow_mut() = primitives;
        Ok(true)
    }

    /// Computes bounding sphere enclosing the path visualization.
    pub fn get_bounding_sphere(
        &self,
        entity: Option<&Entity>,
        result: Option<&mut BoundingSphere>,
    ) -> Result<BoundingSphereState, DeveloperError> {
        let entity = entity.ok_or_else(|| DeveloperError::new("entity is required."))?;
        let result = result.ok_or_else(|| DeveloperError::new("result is required."))?;

        if let Some(data) = self.items.get(&entity.id) {
            let scene = self.scene.borrow();
            let primitives = scene.primitives.borrow();
            if data.primitive_idx < primitives.len() {
                let prim = &primitives[data.primitive_idx];
                *result = prim.bounding_sphere;
                return Ok(BoundingSphereState::Done);
            }
        }

        Ok(BoundingSphereState::Failed)
    }

    /// Returns true if destroyed.
    pub fn is_destroyed(&self) -> bool {
        self.destroyed
    }

    /// Destroys this visualizer.
    pub fn destroy(&mut self) {
        if let Some(sub) = self.collection_subscription.take() {
            self.entity_collection.borrow_mut().collection_changed.remove_listener(sub);
        }
        self.items.clear();
        self.scene.borrow().primitives.borrow_mut().clear();
        self.destroyed = true;
    }
}

impl Drop for PathVisualizer {
    fn drop(&mut self) {
        if !self.destroyed {
            self.destroy();
        }
    }
}
